# p is padded thinning result, sk local
from collections import defaultdict,deque
lab,n=ndi.label(m,structure=np.ones((3,3)))
# adjacency per skeleton px, suppress diagonal shortcuts
coords=[tuple(p) for p in np.argwhere(sk)]
S=set(coords);adj={p:[] for p in S}
for y,x in S:
 for dy in [-1,0,1]:
  for dx in [-1,0,1]:
   if not (dx or dy): continue
   q=(y+dy,x+dx)
   if q not in S: continue
   if dx and dy and ((y,x+dx) in S or (y+dy,x) in S): continue
   adj[(y,x)].append(q)
deg={p:len(a) for p,a in adj.items()}
for i,sl in enumerate(ndi.find_objects(lab),1):
 if not sl:continue
 sy,sx=sl; cm=(lab[sy,sx]==i); pts={p for p in S if cm[p[0],p[1]]}
 # collapse adjacent key nodes degree !=2 into clusters
 key={p for p in pts if deg[p]!=2}
 seen=set(); clusters=[]
 for p in key:
  if p in seen:continue
  st=[p];seen.add(p);cl=[]
  while st:
   a=st.pop();cl.append(a)
   for b in adj[a]:
    if b in key and b not in seen:seen.add(b);st.append(b)
  clusters.append(cl)
 cid={p:k for k,c in enumerate(clusters) for p in c}
 print('\nCOMP',i,'bbox',(sx.start+x0,sy.start+y0,sx.stop+x0-1,sy.stop+y0-1),'skeleton px',len(pts),'keys',len(key),'clusters',len(clusters))
 for k,c in enumerate(clusters):
  ys0=[p[0]+y0 for p in c];xs0=[p[1]+x0 for p in c]
  print(' node',k,'degtypes',sorted(set(deg[p] for p in c)), 'centroid',(round(np.mean(xs0),1),round(np.mean(ys0),1)),'n',len(c))
 # trace edges from cluster boundary
 edge_seen=set(); edges=[]
 for p in key:
  for q in adj[p]:
   if q in key and cid[p]==cid[q]: continue
   e=tuple(sorted((p,q)))
   if e in edge_seen:continue
   edge_seen.add(e)
   if q in key:
    edges.append((cid[p],cid[q],2,p,q));continue
   path=[p,q]; prev=p; cur=q
   while cur not in key:
    ns=[n for n in adj[cur] if n!=prev]
    if not ns:break
    nxt=ns[0];edge_seen.add(tuple(sorted((cur,nxt))));path.append(nxt);prev,cur=cur,nxt
   if cur in key:edges.append((cid[p],cid[cur],len(path),p,cur))
 print(' edges',[(a,b,L,(s[1]+x0,s[0]+y0),(e[1]+x0,e[0]+y0)) for a,b,L,s,e in edges])
